mapper.select:
SELECT o.id, o.order_no, o.user_id, o.custom_design_id, o.total_amount, o.pay_amount, o.status, o.pay_status, o.receiver_name, o.receiver_phone, o.receiver_address, o.remark, o.merchant_remark, o.paid_at, o.confirmed_at, o.produced_at, o.shipped_at, o.completed_at, o.cancelled_at, o.created_at, o.updated_at, oi.id AS item_id, oi.order_id AS item_order_id, oi.product_id AS item_product_id, oi.custom_design_id AS item_custom_design_id, oi.product_name AS item_product_name, oi.product_image AS item_product_image, oi.pattern_id AS item_pattern_id, oi.pattern_image_url AS item_pattern_image_url, oi.preview_image_url AS item_preview_image_url, oi.quantity AS item_quantity, oi.unit_price AS item_unit_price, oi.total_price AS item_total_price, oi.created_at AS item_created_at FROM orders o LEFT JOIN order_item oi ON o.id = oi.order_id AND oi.deleted = 0 WHERE o.deleted = 0
AND o.status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_name LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_phone LIKE CONCAT('%', #{keyword}, '%'))
AND o.created_at >= #{startTime}
AND o.created_at <= #{endTime}
ORDER BY o.created_at DESC
